import{_ as p,C as s,o as u,c as h,a6 as d,E as t,j as a,a as o,w as i}from"./chunks/framework.DtxWasON.js";const C=JSON.parse('{"title":"Network Upgrade: 8-vaxildan","description":"","frontmatter":{},"headers":[],"relativePath":"mainchain/migrations/8-vaxildan_upgrade.md","filePath":"mainchain/migrations/8-vaxildan_upgrade.md"}'),g={name:"mainchain/migrations/8-vaxildan_upgrade.md"};function m(v,e,k,b,f,y){const l=s("InstallUnd"),n=s("CosmovisorDirTree"),r=s("PluginTabsTab"),c=s("PluginTabs");return u(),h("div",null,[e[4]||(e[4]=d('<h1 id="network-upgrade-8-vaxildan" tabindex="-1">Network Upgrade: 8-vaxildan <a class="header-anchor" href="#network-upgrade-8-vaxildan" aria-label="Permalink to &quot;Network Upgrade: 8-vaxildan&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>MainNet</strong> upgraded to <code>8-vaxildan</code> in block <strong>24,172,000</strong> on Wednesday 28 October 2026 at 15:24 UTC, following governance proposal 32.</p><p><strong>Use <code>und</code> v1.13.4</strong> for this upgrade.</p><p><strong>TestNet</strong> upgraded to <code>8-vaxildan</code> in block <strong>25,638,900</strong> on 11 August 2026, and has been running v1.13.4 since 20 August 2026.</p></div><div class="tip custom-block"><p class="custom-block-title">Note</p><p>This guide is for operators already running a node, and only for <strong>before</strong> the upgrade&#39;s target block height.</p><p>For new nodes or upgrades <strong>after</strong> the upgrade&#39;s target block height, please see the <a href="./../software/cosmovisor/install_und_with_cosmovisor.html">Install und with Cosmovisor</a> documentation.</p></div><h2 id="about-this-upgrade" tabindex="-1">About this upgrade <a class="header-anchor" href="#about-this-upgrade" aria-label="Permalink to &quot;About this upgrade&quot;">​</a></h2><p><code>8-vaxildan</code> updates the Cosmos SDK to <a href="https://github.com/cosmos/cosmos-sdk/releases/tag/v0.54.4" target="_blank" rel="noreferrer">v0.54.4</a>, IBC to <a href="https://github.com/cosmos/ibc-go/releases/tag/v11.2.0" target="_blank" rel="noreferrer">v11.2.0</a> and CometBFT to <a href="https://github.com/cometbft/cometbft/releases/tag/v0.39.4" target="_blank" rel="noreferrer">v0.39.4</a>.</p><p>Cosmos SDK v0.54.4 is an upstream <strong>security release</strong> and is <strong>state-breaking</strong>, so a coordinated network upgrade is required.</p><p>Alongside the dependency updates, <code>8-vaxildan</code> includes:</p><ul><li><strong>Multi-denomination Payment Streams.</strong> A sender and receiver pair may now run several concurrent streams in different denominations, each with its own deposit, flow rate and claim schedule. Existing streams are migrated automatically and require no action.</li><li><strong>Payment Streams moved to a standalone module</strong>, <a href="https://github.com/unification-com/x-stream" target="_blank" rel="noreferrer">x-stream</a>, consumed by <code>und</code> as an external dependency. This is wire-preserving — existing streams are unaffected.</li><li><strong>BEACON timestamp <code>metadata</code></strong> — an optional, 256-byte descriptor on each timestamp — plus a new <code>BeaconTimestampsByHash</code> query for looking a stamped hash up directly. The hash index is <strong>forward-only</strong>: existing BEACON records are not rewritten or backfilled.</li><li><strong><code>x/group</code> and <code>x/circuit</code> modules removed</strong> (both verified empty on TestNet and MainNet).</li><li><strong>CLI commands migrated to autocli.</strong> Backwards-compatible flag aliases and shims are in place for the custom module commands — see the release notes if you script against <code>und tx</code>.</li></ul><div class="tip custom-block"><p class="custom-block-title">Note for node operators</p><p>There are <strong>no configuration file changes</strong> required for this upgrade. <code>app.toml</code>, <code>config.toml</code> and <code>client.toml</code> carry over as they are.</p></div><p>There are two possible methods for upgrading:</p><ol><li>Automatically, using Cosmovisor (recommended)</li><li>Manually</li></ol><h2 id="automatically-upgrade-from-und-v1-12-x-to-v1-13-x-using-cosmovisor" tabindex="-1">Automatically upgrade from und v1.12.x to v1.13.x using Cosmovisor <a class="header-anchor" href="#automatically-upgrade-from-und-v1-12-x-to-v1-13-x-using-cosmovisor" aria-label="Permalink to &quot;Automatically upgrade from und v1.12.x to v1.13.x using Cosmovisor&quot;">​</a></h2><p><strong>IMPORTANT:</strong> This guide assumes the reader has implemented the required changes outlined in <a href="./cosmovisor.html">Using Cosmovisor with und: Quick Start</a> and migrated their services before using this guide.</p><h3 id="configuring-cosmovisor" tabindex="-1">Configuring Cosmovisor <a class="header-anchor" href="#configuring-cosmovisor" aria-label="Permalink to &quot;Configuring Cosmovisor&quot;">​</a></h3><p>The following can be implemented well in advance of the actual upgrade occurring, which will allow for a completely automated upgrade.</p><p><strong>IMPORTANT</strong> During the upgrade, <code>cosmovisor</code> will automatically do a full backup of the <code>.und_mainchain/data</code> directory. Ensure your host has adequate disk space to accommodate the backup. This may add significant time to the upgrade process, and as such, the process may take up to 30 minutes before the node comes back online.</p><div class="tip custom-block"><p class="custom-block-title">Skipping the Cosmovisor backup</p><p>If you keep your own backups, you can skip Cosmovisor&#39;s by setting <code>UNSAFE_SKIP_BACKUP=true</code> in Cosmovisor&#39;s environment, so that your node comes back online quickly. Blocks resume once validators holding more than two thirds of the voting power are back online, so a quick restart from every validator keeps the halt short.</p></div><div class="tip custom-block"><p class="custom-block-title">Note</p><p>the following commands assume the <code>und</code> home directory is the default location <code>$HOME/.und_mainchain</code>. Modify directory locations as applicable.</p></div><h4 id="_1-create-the-cosmovisor-upgrade-plan-directory" tabindex="-1">1. Create the Cosmovisor upgrade plan directory <a class="header-anchor" href="#_1-create-the-cosmovisor-upgrade-plan-directory" aria-label="Permalink to &quot;1. Create the Cosmovisor upgrade plan directory&quot;">​</a></h4><p>This will be dependent on how you configured <code>cosmovisor</code>, and your actual <code>.und_mainchain</code> path:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.und_mainchain/cosmovisor/upgrades/8-vaxildan/bin</span></span></code></pre></div><h4 id="_2-download-the-latest-und-v1-13-x-and-add-to-cosmovisor-s-upgrades-directory" tabindex="-1">2. Download the latest <code>und</code> v1.13.x and add to Cosmovisor&#39;s <code>upgrades</code> directory <a class="header-anchor" href="#_2-download-the-latest-und-v1-13-x-and-add-to-cosmovisor-s-upgrades-directory" aria-label="Permalink to &quot;2. Download the latest `und` v1.13.x and add to Cosmovisor&#39;s `upgrades` directory&quot;">​</a></h4>',22)),t(l,{version:"1.13.4",plan:"8-vaxildan"}),e[5]||(e[5]=a("p",null,[o("Check the version output is "),a("code",null,"1.13.4"),o("!")],-1)),e[6]||(e[6]=a("p",null,[o("The directory structure for "),a("code",null,"$HOME/.und_mainchain/cosmovisor"),o(" should now look as follows:")],-1)),t(c,null,{default:i(()=>[t(r,{label:"MainNet"},{default:i(()=>[e[0]||(e[0]=a("h4",{id:"mainnet",tabindex:"-1"},[o("MainNet "),a("a",{class:"header-anchor",href:"#mainnet","aria-label":'Permalink to "MainNet"'},"​")],-1)),e[1]||(e[1]=a("p",null,[a("strong",null,"Note:"),o(" 1st upgrade path name is "),a("code",null,"1-init_ibc")],-1)),t(n,{network:"mainnet",plan:"8-vaxildan",upgraded:"false"})]),_:1}),t(r,{label:"TestNet"},{default:i(()=>[e[2]||(e[2]=a("h4",{id:"testnet",tabindex:"-1"},[o("TestNet "),a("a",{class:"header-anchor",href:"#testnet","aria-label":'Permalink to "TestNet"'},"​")],-1)),e[3]||(e[3]=a("p",null,[a("strong",null,"Note:"),o(" 1st upgrade path name is "),a("code",null,"1-ibc")],-1)),t(n,{network:"testnet",plan:"8-vaxildan",upgraded:"true"})]),_:1})]),_:1}),e[7]||(e[7]=d(`<p>That&#39;s it! When the upgrade height specified in the governance proposal is reached, Cosmovisor and the <code>upgrade</code> module will handle the rest automatically.</p><h3 id="cosmovisor-upgrade-process-overview" tabindex="-1">Cosmovisor Upgrade process overview <a class="header-anchor" href="#cosmovisor-upgrade-process-overview" aria-label="Permalink to &quot;Cosmovisor Upgrade process overview&quot;">​</a></h3><p>Briefly, at the upgrade height, Cosmovisor will automatically:</p><ol><li>Stop the <code>und</code> v1.12.x binary</li><li>Backup <code>.und_mainchain/data</code> to <code>.und_mainchain/data-backup-YYYY-M-DD</code><strong>*</strong></li><li>Reconfigure itself to use <code>und</code> v1.13.x</li><li>Restart <code>und</code> using the new version</li></ol><p><strong>*Ensure the host has enough space to back up!</strong></p><h2 id="manual-upgrade-not-recommended" tabindex="-1">Manual upgrade (not recommended) <a class="header-anchor" href="#manual-upgrade-not-recommended" aria-label="Permalink to &quot;Manual upgrade (not recommended)&quot;">​</a></h2><p>The alternative to implementing Cosmovisor is to manually upgrade the binary. Once the upgrade height specified in the governance proposal is reached, the <code>upgrade</code> module will automatically halt the node via a <code>panic</code>. The node operator will then need to:</p><ol><li>Stop the <code>und</code> v1.12.x binary, via <code>systemd</code> or their chosen method</li><li>Backup the <code>und_mainchain/data</code> directory</li><li>Download and install the latest <code>und</code> v1.13.x, replacing the old v1.12.x binary (for example in <code>/usr/local/bin</code>)</li><li>Restart the <code>und</code> binary, via <code>systemd</code> or their chosen method.</li></ol><p>Since the process involves manual intervention, monitoring and execution, the process may take longer.</p><h2 id="after-the-upgrade" tabindex="-1">After the upgrade <a class="header-anchor" href="#after-the-upgrade" aria-label="Permalink to &quot;After the upgrade&quot;">​</a></h2><p>Once the node is back up, verify it is running the new binary and that the upgrade was applied:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">und</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log_level=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">und</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> query</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> applied</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 8-vaxildan</span></span></code></pre></div>`,12))])}const _=p(g,[["render",m]]);export{C as __pageData,_ as default};
